// Partie 2 · Découpe laser et impression UV — même mécanique que la partie 1 (app.js), état séparé.
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// Lien de l’appli de l’exercice final : à renseigner quand elle sera publiée.
const APP_URL='';

const STORE='df-idee-objet-p2';
const initial={page:0,scenario:0,sector:0,reveal:{},quiz:{},laserStep:0,laserLayer:'cut',power:60,speed:50,uvStep:0,uvSupport:'noir',uvWhite:false,uvHiRes:true,material:'bois',truths:[],recap:[],elapsed:0,runningSince:null};
let state={...initial};try{const saved=JSON.parse(sessionStorage.getItem(STORE)||'null');if(saved)state={...initial,...saved};}catch{}
function save(){try{sessionStorage.setItem(STORE,JSON.stringify(state));}catch{}}
function elapsed(){return state.elapsed+(state.runningSince?Math.max(0,Date.now()-state.runningSince):0);}

const plan=[
 ['Le déclic','00–10',10,'Tu ferais comment, toi ?','Montre les trois situations, environ 3 minutes chacune. Fais décrire l’objet, puis demande comment on pourrait le fabriquer. Ne donne pas encore le nom des machines : laisse les idées venir.','Certaines formes se découpent dans une plaque, d’autres demandent de la couleur posée sur un objet. Ce sont deux familles de machines différentes.'],
 ['Les usages métiers','10–22',22,'Qui utilise ces machines dans son travail ?','Explore les cinq cas réels, environ 2 minutes chacun. Montre la photo, lis l’accroche, laisse le groupe proposer une réponse, puis touche chaque question. « Voir la source du cas » ouvre le témoignage d’origine.','Le laser et l’UV servent dans beaucoup de métiers, souvent ensemble : on découpe une forme, puis on y imprime ou grave une information.'],
 ['Deux machines, deux gestes','22–30',30,'L’une enlève, l’autre dépose. Laquelle fait quoi ?','Présente les deux cartes, puis fais le petit jeu « Laquelle ? » en grand groupe. Chacun répond avant de toucher.','Le laser enlève de la matière avec de la lumière concentrée. L’imprimante UV dépose de l’encre que la lumière UV durcit aussitôt.'],
 ['Le laser, pas à pas','30–45',45,'Comment un dessin devient-il une découpe ?','Parcours les quatre onglets. Sur « Puissance et vitesse », fais prédire le résultat avant de bouger les curseurs. Si possible, montre une chute de test réelle avec plusieurs réglages.','Le fichier dit où passer, les réglages disent comment. Trop peu d’énergie : ça marque. Trop : ça brûle. On teste toujours sur une chute.'],
 ['L’UV, pas à pas','45–60',60,'Comment la couleur tient-elle sur un carreau ou une plaque ?','Parcours les quatre onglets. Sur « Le blanc », fais essayer le support noir puis transparent, avec et sans couche de blanc. Montre si possible un échantillon imprimé avec et sans blanc.','L’encre UV est durcie par la lumière dès qu’elle est posée. Sur un support foncé ou transparent, une couche de blanc sous la couleur la fait ressortir.'],
 ['Quelle matière ?','60–72',72,'Peut-on tout mettre dans ces machines ?','Fais circuler des échantillons. Pour chaque matière, demande d’abord : couper, graver, imprimer ? Puis affiche la fiche.','Chaque matière réagit différemment. Certaines sont interdites au laser, comme le PVC. La liste de la machine utilisée fait toujours foi.'],
 ['Les limites','72–82',82,'Vrai ou faux ?','Lis chaque affirmation à voix haute. Vote à main levée, puis retourne la carte. Insiste sur la surveillance du laser et les matières interdites.','Les règles de sécurité ne sont pas négociables : on reste près du laser, on ne découpe jamais une matière inconnue, et le formateur valide chaque lancement.'],
 ['À toi de créer','82–112',112,'Qu’est-ce que tu vas fabriquer ?','Distribue le lien de l’appli. Laisse 20 minutes de création. Valide chaque fichier : matière, machine, taille et durée. Lance les fabrications en ordre, une personne par machine à la fois.','Passer d’une idée à un fichier, puis à un objet : c’est le même chemin qu’en impression 3D, avec d’autres outils.'],
 ['Le bilan','112–120',120,'Qu’as-tu découvert en passant de l’écran à la matière ?','Fais un tour de table, objet en main si possible. 30 secondes par personne.','Chacun repart en sachant quelle machine choisir pour quel besoin, et ce qu’il faut vérifier avant de lancer.']
];

