 zodio:{author:'Trotec Laser',title:'Zôdio, France',url:'https://www.troteclaser.com/fr/a-propos-de-nous/temoignages-clients/zodio',note:'20 magasins équipés d’un laser dans leurs ateliers de personnalisation ; gravure et découpe sur bois, verre et cuir.'},
