function sceneBoite(){const f=(x,y)=>`<path d="M${x} ${y}h40v-12h40v12h40v-12h40v12h40v120h-200z" fill="${wood}" stroke="#e8485f" stroke-width="3"/>`;return `<svg viewBox="0 0 600 450" role="img" aria-label="Une planche de bois sur laquelle sont dessinées les pièces d’une boîte à assembler, avec leurs créneaux. Les traits de coupe sont en rouge."><rect width="600" height="450" fill="#1f2530"/><rect x="40" y="60" width="520" height="330" rx="6" fill="#c7a679"/>${f(70,110)}${f(310,110)}${f(70,250)}<rect x="310" y="250" width="200" height="110" fill="${wood}" stroke="#e8485f" stroke-width="3" stroke-dasharray="10 6"/><text x="410" y="312" text-anchor="middle" font-family="Poppins,Arial,sans-serif" font-size="18" fill="#6d4a24">fond</text></svg>`;}
const scenarios=[
 {title:'Un prénom.<br>Sur du bois.<br><span class="orange">Mais comment ?</span>',text:'Tu veux offrir une plaque de porte avec un prénom bien net.',ask:'Comment écrire dans le bois sans peinture ni pinceau ?',photo:'Graver.<br>Marquer la surface.',scene:scenePlaque},
 {title:'Une boîte.<br>Sans clou.<br><span class="orange">Ça tient ?</span>',text:'Les pièces d’une boîte sont dessinées à plat sur une planche. Elles s’emboîtent par des créneaux.',ask:'Comment découper ces formes avec précision, toutes identiques ?',photo:'Découper.<br>Assembler à plat.',scene:sceneBoite},
 {title:'Une image.<br>Sur un carreau.<br><span class="orange">En couleur ?</span>',text:'Un logo doit apparaître sur des carreaux de céramique, posés côte à côte.',ask:'Comment mettre une image sur un objet rigide, sans autocollant ?',photo:'Imprimer.<br>Directement sur l’objet.',image:'p2-uv-carreaux.webp',alt:'Une imprimante UV à plat imprime un grand logo Digital Factory noir sur un ensemble de carreaux blancs alignés sur sa table.'}
];
function screen0(){const s=scenarios[state.scenario];const visual=s.image?`<img src="assets/${s.image}" alt="${escape(s.alt)}">`:s.scene();return `${kicker(0)}<div class="hero"><div class="hero-copy"><div><h1>${s.title}</h1><p class="lede">${s.text}</p><div class="scenario-tabs">${['Graver','Découper','Imprimer'].map((x,i)=>`<button class="pill" data-scenario="${i}" aria-pressed="${state.scenario===i}">${x}</button>`).join('')}</div></div><div class="challenge"><span class="symbol" aria-hidden="true">?</span><p><strong>Et toi, tu ferais comment ?</strong>${s.ask}</p></div></div><figure class="hero-visual scenario-visual p2-scene" style="margin:0">${visual}<span class="photo-label">LASER &amp; UV</span><figcaption class="photo-caption"><strong>${s.photo}</strong><span>${s.image?'Visuel d’illustration':'Schéma d’illustration'}</span></figcaption></figure></div>`;}

