const T='https://www.troteclaser.com/static_processed/';
const sectors=[
 {name:'Industrie',starter:'Chez MM Engineering, chaque pièce métallique porte ses données de production gravées au laser.',image:T+'70343eaf52e3af3e38bd135e8117488a/accessoires-rotatifs-de-precision-en-metal-pour-les-machines-de-gravure-laser-trotec-avec-marquage-laser.jpg?{%22image%22:%22https://backend.troteclaser.com/static/images/about-trotec/trotec-customers/MMEngineering/Bauteil_Laserbeschriftet_5.jpg%22,%22edits%22:{%22resize%22:{%22width%22:640,%22fit%22:%22cover%22}},%22outputFormat%22:{%22format%22:%22webp%22}}',alt:'Pièces métalliques de précision portant un marquage gravé au laser.',credit:'Photo : Trotec Laser · MM Engineering, Bavière',source:'mm',qa:[['Avant, l’entreprise utilisait des étiquettes ou un prestataire extérieur. Qu’est-ce qui pouvait poser problème ?','Des délais plus longs, et des étiquettes qui peuvent s’abîmer. Depuis 2021, l’entreprise grave elle-même : le marquage est plus rapide, résiste au vieillissement et reste lisible en permanence.'],['Pourquoi graver un numéro directement sur la pièce ?','Pour la traçabilité : on peut retrouver l’origine de la pièce pendant toute sa vie, de la fabrication à la réparation. Ici, c’est un laser de marquage adapté au métal, différent d’un laser CO₂ d’atelier.']],applications:'Numéros de série · Codes QR et codes-barres · Logos · Plaques signalétiques de machines'},
 {name:'Signalétique',starter:'Ces panneaux à pictogramme sont découpés au laser dans l’atelier de Signbox, près de Londres.',image:T+'4e3f7a643d596fc49a5214444cc8a914/signbox-application-03.jpg?{%22image%22:%22https://backend.troteclaser.com/static/images/knowledge/case-studies/signbox/Signbox-Application-03.jpg%22,%22edits%22:{%22resize%22:{%22width%22:650,%22fit%22:%22cover%22}},%22outputFormat%22:{%22format%22:%22webp%22}}',alt:'Panneau d’accessibilité en bambou avec un pictogramme de fauteuil roulant en acrylique noir découpé au laser.',credit:'Photo : Trotec Laser · Signbox, Royaume-Uni',source:'signbox',qa:[['Pourquoi découper l’acrylique au laser plutôt qu’avec une fraiseuse ?','Le laser laisse un bord poli sur l’acrylique et découpe aussi les matières avec support adhésif, ce que leurs fraiseuses ne permettent pas. Sa précision réduit le gaspillage de matière.'],['L’atelier a aussi des imprimantes UV. Comment faire tomber la découpe pile autour de l’impression ?','Une caméra sur le laser repère la plaque imprimée et ajuste automatiquement le tracé de découpe. Les pictogrammes courants sont enregistrés comme modèles dans le logiciel.']],applications:'Plaques de porte · Lettrage · Présentoirs · Enseignes intérieures et extérieures'},
 {name:'Objets en série',starter:'Ces porte-clés en acrylique sont d’abord imprimés en UV, puis découpés au laser, par dizaines de milliers.',image:T+'26194665d7c7c9035c4ce7eda1e5f9aa/mcorporation_acrylickeychain_hukusuu_img_6353.jpg?{%22image%22:%22https://backend.troteclaser.com/static/images/about-trotec/trotec-customers/MCorporation/MCORPORATION_Acrylickeychain_hukusuu_IMG_6353.jpg%22,%22edits%22:{%22resize%22:{%22width%22:650,%22fit%22:%22cover%22}},%22outputFormat%22:{%22format%22:%22webp%22}}',alt:'Porte-clés en acrylique imprimés en couleur et découpés au laser, de formes et de motifs variés.',credit:'Photo : Trotec Laser · M-Corporation, Osaka',source:'mcorp',qa:[['Dans quel ordre passent les deux machines ? Pourquoi ?','D’abord l’impression UV : sept imprimantes, alimentées par un bras robotisé, impriment les plaques d’acrylique. Le lendemain matin, le laser découpe le contour de chaque dessin ; une caméra ajuste la découpe à l’impression.'],['Combien de pièces une seule machine laser peut-elle produire ?','Jusqu’à 3 000 pièces par jour, avec 50 dessins par plaque. Des commandes de 50 000 porte-clés en deux semaines sont fréquentes ; en période de pointe, l’entreprise produit jusqu’à 300 000 articles par mois.']],applications:'Porte-clés · Figurines sur socle · Badges · Objets publicitaires'},
 {name:'Commerce',starter:'Dans les 20 magasins Zôdio en France, un atelier grave et découpe les objets au nom du client.',image:T+'b26ed25ba8d8c4ed6d75b40d7fa6e8bc/coffret-cadeau-en-bois-grave-au-laser-avec-la-mention-%22papa-sommelier%22-cree-avec-le-laser-trotec-co..jpg?{%22image%22:%22https://backend.troteclaser.com/static/images/knowledge/case-studies/zodio/Zodio-application-07.jpg%22,%22edits%22:{%22resize%22:{%22width%22:650,%22fit%22:%22cover%22}},%22outputFormat%22:{%22format%22:%22webp%22}}',alt:'Coffret cadeau en bois gravé au laser avec la mention « Papa Sommelier ».',credit:'Photo : Trotec Laser · Zôdio, France',source:'zodio',qa:[['Pourquoi un magasin de décoration installe-t-il un laser dans ses rayons ?','Pour proposer un service « fait pour moi » : le client choisit un objet et repart avec une pièce unique. Selon l’enseigne, la personnalisation crée un lien fort avec le client et la distingue de la concurrence.'],['Sur quelles matières l’équipe travaille-t-elle ?','Surtout le bois — planches, rondins, boîtes — mais aussi le verre et le cuir. La machine est fermée : l’équipe n’a pas besoin d’équipement de protection individuelle pendant le traitement.']],applications:'Planches gravées · Boîtes cadeaux · Décorations et étiquettes de mariage'},
 {name:'Mode',starter:'Une collection de haute couture « zéro déchet », découpée et gravée au laser.',image:T+'1775c2bdeaba098077d6db17f0dcc5a9/lea-application-02-small.jpg?{%22image%22:%22https://backend.troteclaser.com/static/images/knowledge/case-studies/Lea/Lea-application-02-small.jpg%22,%22edits%22:{%22resize%22:{%22width%22:650,%22fit%22:%22cover%22}},%22outputFormat%22:{%22format%22:%22webp%22}}',alt:'Mannequin portant un vêtement translucide découpé au laser, aux motifs circulaires superposés.',credit:'Photo : Trotec Laser · Lea Lahr-Thiele, Hambourg',source:'lea',qa:[['Qu’apporte le laser à une couturière ?','Des découpes très fines et nettes, même dans des tissus délicats comme la soie ou le polyester recyclé. La découpe et la gravure se font en un seul passage.'],['Comment éviter de jeter les chutes de tissu ?','Lea a mis au point une méthode qu’elle appelle « Counterform-Design » : elle compose de nouvelles pièces avec les formes découpées et les chutes. Sa collection de sept tenues a reçu le prix de la meilleure collection à l’exposition des diplômés de Hambourg en 2023.']],applications:'Motifs découpés dans le tissu · Cuir gravé · Accessoires · Prototypes de patrons'}
];
function screen1(){const c=sectors[state.sector];return `${kicker(1)}<div class="section-head"><h2>Ça sert à quoi,<br><span class="orange">dans la vraie vie ?</span></h2><p class="lede">Choisis un domaine.<br>Observe, propose, puis vérifie.</p></div><div class="tabbar">${sectors.map((s,i)=>`<button class="tab" data-sector="${i}" aria-pressed="${state.sector===i}">${s.name}</button>`).join('')}</div><div class="case-layout"><div><figure class="case-photo p2-case-photo"><img src="${c.image}" alt="${escape(c.alt)}" referrerpolicy="no-referrer"><figcaption><span>${c.credit}</span><span>0${state.sector+1} / 0${sectors.length}</span></figcaption></figure></div><div class="case-panel"><span class="case-domain">${c.name.toUpperCase()} · CAS RÉEL</span><h3>${c.starter}</h3><p class="case-applications"><strong>D’autres usages dans ce secteur</strong><span>${c.applications}</span></p><p class="case-hint">Propose ta réponse, puis touche une question.</p><div class="case-questions">${c.qa.map(([question,answer],i)=>{const revealed=!!state.reveal?.[`c-${state.sector}-${i}`];return `<button class="case-question" data-case="${i}" aria-expanded="${revealed}"><span class="case-question-top"><strong>${question}</strong><span aria-hidden="true">${revealed?'−':'+'}</span></span>${revealed?`<span class="case-question-body case-answer">${answer}</span>`:''}</button>`;}).join('')}</div><button class="text-link" data-source="${c.source}">Voir la source du cas ↗</button><p class="micro muted">Touche une question pour afficher ou masquer la réponse.</p></div></div>`;}

// ——— Deux machines ———
const quiz=[
 ['Découper un pochoir dans du carton','laser','Le laser suit le contour et traverse le carton.'],
 ['Mettre une photo en couleur sur un carreau','uv','Seule l’imprimante UV dépose de la couleur.'],
 ['Graver un prénom sur une planche en bois','laser','Le laser brûle légèrement la surface : le texte apparaît, sans encre.'],
 ['Un porte-clés en acrylique avec un logo en couleur','both','Le laser découpe la forme, puis l’UV imprime le logo. Les deux machines se complètent.'],
 ['Un texte blanc sur une plaque noire','uv','L’UV peut imprimer de l’encre blanche. Le laser, lui, ne pose aucune couleur.']
];
const qLabel={laser:'Laser',uv:'UV',both:'Les deux'};
function screen2(){return `${kicker(2)}<div class="section-head"><h2>L’une enlève.<br><span class="orange">L’autre dépose.</span></h2><p class="lede">Deux machines, deux gestes.<br>Repère ce qui les distingue.</p></div><div class="p2-duo"><article class="p2-machine laser"><span class="eyebrow">DÉCOUPE &amp; GRAVURE LASER</span><h3>Elle enlève de la matière.</h3><p>Un faisceau de lumière très concentré chauffe la matière jusqu’à la vaporiser, le long d’un trajet précis.</p><ul><li><strong>Couper</strong> : le faisceau traverse la plaque.</li><li><strong>Graver</strong> : il n’attaque que la surface.</li><li><strong>Fichier</strong> : un dessin en traits (vectoriel) ou une image à graver.</li></ul></article><article class="p2-machine uv"><span class="eyebrow">IMPRESSION UV</span><h3>Elle dépose de l’encre.</h3><p>Des têtes projettent de minuscules gouttes d’encre. Une lampe UV les durcit aussitôt : l’objet sort sec.</p><ul><li><strong>Imprimer</strong> : couleur, blanc, vernis, parfois relief.</li><li><strong>Supports</strong> : objets plutôt plats et rigides.</li><li><strong>Fichier</strong> : une image ou un visuel en couleur.</li></ul></article></div><div class="p2-quiz"><div class="p2-quiz-head"><span class="eyebrow">LAQUELLE ?</span><p class="small muted">Réponds d’abord à voix haute, puis touche ton choix.</p></div>${quiz.map(([need,good,why],i)=>{const a=state.quiz[i];return `<div class="p2-quiz-row"><p class="p2-need">${need}</p><div class="p2-quiz-choices" role="group" aria-label="${escape(need)}">${Object.keys(qLabel).map(k=>`<button class="pill" data-quiz="${i}" data-answer="${k}" aria-pressed="${a===k}">${qLabel[k]}</button>`).join('')}</div>${a?`<p class="p2-quiz-feedback ${a===good?'ok':'ko'}" role="status"><strong>${a===good?'Oui.':'Pas tout à fait.'}</strong> ${a===good?'':`Réponse : ${qLabel[good]}. `}${why}</p>`:''}</div>`;}).join('')}</div>`;}

// ——— Laser pas à pas ———
const laserSteps=[
 ['Le fichier','Le laser suit des traits pour couper et balaie des surfaces pour graver. Dans le logiciel, chaque couleur du dessin reçoit ses propres réglages.','La couleur d’un trait sert d’instruction : elle ne sera pas « imprimée ».','Sur ce porte-clés, qu’est-ce qui sera coupé ? Et gravé ?'],
 ['La préparation','La plaque est posée bien à plat. On fait la mise au point (la bonne distance entre la tête et la matière), on place le point de départ, puis on choisit la matière dans le logiciel.','L’aspiration des fumées doit tourner avant de lancer.','Que se passe-t-il si la plaque est gondolée ?'],
 ['Puissance et vitesse','Deux réglages décident du résultat : la puissance du faisceau et la vitesse de la tête. Beaucoup d’énergie au même endroit : ça creuse ou ça coupe.','Valeurs fictives pour comprendre. Les vrais réglages dépendent de la machine et de la matière : on les teste sur une chute.','Prédit le résultat avant de bouger les curseurs.'],
 ['Fumée et surveillance','La matière vaporisée produit des fumées, et parfois une petite flamme. Le capot reste fermé, l’aspiration tourne, et quelqu’un reste près de la machine pendant toute la découpe.','On ne quitte jamais un laser en marche.','Pourquoi la découpe produit-elle de la fumée ?']
];
const layerInfo={cut:['Coupe','Trait rouge fin : le laser traverse la plaque et suit le contour.','#e8485f'],engrave:['Gravure','Surface noire : le laser balaie la zone ligne par ligne et creuse légèrement.',ink],mark:['Marquage','Trait bleu : passage léger, juste pour dessiner un repère.','#2f7fd9']};
function keychainSVG(){const on=k=>state.laserLayer===k?1:.22;return `<svg viewBox="0 0 600 360" role="img" aria-label="Fichier d’un porte-clés : contour rouge pour la coupe, texte noir pour la gravure, trait bleu pour le marquage. Calque mis en avant : ${layerInfo[state.laserLayer][0]}."><rect width="600" height="360" fill="#f4f3f8"/><g opacity="${on('cut')}"><rect x="110" y="80" width="380" height="200" rx="40" fill="none" stroke="#e8485f" stroke-width="4"/><circle cx="160" cy="130" r="16" fill="none" stroke="#e8485f" stroke-width="4"/></g><g opacity="${on('engrave')}"><text x="320" y="205" text-anchor="middle" font-family="Poppins,Arial,sans-serif" font-size="60" font-weight="800" fill="${ink}">SAMI</text></g><g opacity="${on('mark')}"><path d="M200 240H440" stroke="#2f7fd9" stroke-width="3" stroke-dasharray="2 8" stroke-linecap="round"/></g></svg>`;}
function prepSVG(){return `<svg viewBox="0 0 600 360" role="img" aria-label="Vue de côté : la tête laser au-dessus d’une plaque posée à plat ; la distance de mise au point est indiquée, ainsi que l’aspiration des fumées."><rect width="600" height="360" fill="#f4f3f8"/><rect x="250" y="40" width="100" height="90" rx="8" fill="${ink}"/><path d="M285 130h30l-8 28h-14z" fill="#8d93a0"/><path d="M300 158V250" stroke="${flash}" stroke-width="3"/><path d="M380 160V250" stroke="${mauve}" stroke-width="2"/><path d="m374 168 6-8 6 8M374 242l6 8 6-8" stroke="${mauve}" stroke-width="2" fill="none"/><text x="392" y="210" font-family="Poppins,Arial,sans-serif" font-size="16" fill="${ink}">mise au point</text><rect x="90" y="250" width="420" height="22" fill="${wood}" stroke="${woodDark}" stroke-width="2"/><path d="M80 272h440" stroke="#6b7280" stroke-width="6"/><text x="90" y="300" font-family="Poppins,Arial,sans-serif" font-size="16" fill="${ink}">Plaque bien à plat</text><path d="M470 90c40 0 60 20 60 50" stroke="#9aa1ad" stroke-width="3" fill="none" stroke-dasharray="6 6"/><text x="440" y="70" font-family="Poppins,Arial,sans-serif" font-size="16" fill="${ink}">aspiration</text></svg>`;}
function laserResult(){const r=state.power/state.speed;if(r<.45)return ['Marquage léger','Le faisceau effleure la surface : un trait clair, presque invisible.',Math.max(.06,r/.45*.15)];if(r<1.1)return ['Gravure','La surface est creusée : le dessin apparaît nettement, sans traverser.',.15+(r-.45)/.65*.5];if(r<2.2)return ['Découpe nette','Le faisceau traverse la plaque : la pièce se détache, bords légèrement brunis.',1];return ['Trop d’énergie','La plaque est traversée mais les bords noircissent et brûlent. On augmente la vitesse ou on baisse la puissance.',1];}
function cutSVG(){const [label,,depth]=laserResult();const burnt=label==='Trop d’énergie';const t=60,top=150,d=Math.min(1,depth)*t,w=burnt?26:depth>=1?10:8;return `<svg viewBox="0 0 600 300" role="img" aria-label="Coupe d’une plaque de bois vue de côté. Résultat : ${label}."><rect width="600" height="300" fill="#f4f3f8"/><rect x="250" y="20" width="100" height="70" rx="8" fill="${ink}"/><path d="M285 90h30l-8 26h-14z" fill="#8d93a0"/><path d="M300 116V${top+d}" stroke="${flash}" stroke-width="3"/><rect x="60" y="${top}" width="480" height="${t}" fill="${wood}" stroke="${woodDark}" stroke-width="2"/><path d="M${300-w/2} ${top}h${w}l${-w/4} ${d}h${-w/2}z" fill="${burnt?'#2b2118':'#f4f3f8'}" stroke="${burnt||depth>=1?'#5a3a1a':woodDark}" stroke-width="${burnt?6:2}"/>${depth>=1?`<rect x="${300-w/2}" y="${top+t-1}" width="${w}" height="4" fill="#f4f3f8"/>`:''}<text x="60" y="${top+t+40}" font-family="Poppins,Arial,sans-serif" font-size="18" font-weight="700" fill="${ink}">${label}</text></svg>`;}
function laserStepHTML(i){if(i===0)return `<div class="layer-demo">${keychainSVG()}</div><div class="p2-layer-btns" role="group" aria-label="Calques du fichier">${Object.entries(layerInfo).map(([k,[n]])=>`<button class="pill" data-layer="${k}" aria-pressed="${state.laserLayer===k}"><span class="p2-dot" style="background:${layerInfo[k][2]}"></span>${n}</button>`).join('')}</div><p class="small" role="status">${layerInfo[state.laserLayer][1]}</p>`;if(i===1)return `<div class="layer-demo">${prepSVG()}</div><div class="preparation-checks"><span>Plaque à plat</span><span>Mise au point</span><span>Point de départ</span><span>Matière choisie</span><span>Aspiration en marche</span></div>`;if(i===2){const [label,text]=laserResult();return `<div class="layer-demo" id="cut-drawing">${cutSVG()}</div><div class="range-box"><div class="range-label"><label for="power">Puissance</label><output id="power-out">${state.power} %</output></div><input id="power" type="range" min="10" max="100" step="5" value="${state.power}"></div><div class="range-box"><div class="range-label"><label for="speed">Vitesse</label><output id="speed-out">${state.speed} %</output></div><input id="speed" type="range" min="10" max="100" step="5" value="${state.speed}"></div><p class="small layer-status" id="cut-status" role="status"><strong>${label}.</strong> ${text}</p>`;}return `<div class="p2-safety"><div><span>01</span><strong>Capot fermé</strong><p>La vitre filtre le rayonnement. On regarde à travers, jamais capot ouvert.</p></div><div><span>02</span><strong>Aspiration en marche</strong><p>Les fumées sont aspirées et filtrées avant d’être rejetées.</p></div><div><span>03</span><strong>Quelqu’un reste là</strong><p>Si une flamme dure, on met en pause et on prévient le formateur.</p></div></div>`;}
function stepsTabs(list,key,attr){return `<div class="steps process-steps p2-steps">${list.map((s,i)=>`<button class="step-btn" data-${attr}="${i}" aria-pressed="${state[key]===i}"><span>0${i+1}</span>${s[0]}</button>`).join('')}</div>`;}
function screen3(){const i=state.laserStep,s=laserSteps[i];return `${kicker(3)}<div class="section-head"><h2>Un dessin.<br><span class="orange">Puis un trait de lumière.</span></h2><p class="lede">Du fichier à la découpe,<br>quatre étapes à comprendre.</p></div>${stepsTabs(laserSteps,'laserStep','lstep')}<div class="split process-layout"><div>${laserStepHTML(i)}</div><div class="process-copy"><span class="number">ÉTAPE 0${i+1}</span><h3>${s[0]}</h3><p class="lede">${s[1]}</p><p class="notice">${s[2]}</p><div class="challenge"><span class="symbol" aria-hidden="true">?</span><p>${s[3]}</p></div>${i===3?`<button class="text-link" data-source="trotecMat">Les matières interdites au laser ↗</button>`:''}</div></div>`;}

// ——— UV pas à pas ———
const uvSteps=[
 ['L’image','Photo, logo ou texte : tout part d’un visuel. Une photo doit avoir assez de pixels pour la taille imprimée. Un logo dessiné en vectoriel reste net à toutes les tailles.','Agrandir une petite image ne crée pas de détails : elle devient floue ou pixelisée.','À quelle taille veux-tu imprimer ton image ?'],
 ['Le support','L’objet est posé à plat sur la table. La tête passe juste au-dessus : on règle sa hauteur selon l’épaisseur. La surface doit être propre ; certaines matières demandent une préparation pour que l’encre accroche.','Verre, métal ou céramique : suis la procédure de préparation de l’atelier.','Pourquoi la hauteur de la tête est-elle importante ?'],
 ['Le blanc','Les encres de couleur sont transparentes, comme un feutre. Sur un support foncé ou transparent, la machine peut d’abord poser une couche de blanc, puis la couleur par-dessus.','Essaie un support noir puis transparent, avec et sans blanc.','Sur quel support le blanc est-il indispensable ?'],
 ['Le séchage UV','À chaque passage, une lampe UV durcit les gouttes d’encre : l’objet sort sec et se manipule tout de suite. En superposant des couches, on peut ajouter du vernis ou un léger relief.','Ne regarde pas directement la lampe UV de la machine.','Quelle différence avec une imprimante de bureau ?']
];
const supports={blanc:['Blanc','#ffffff'],bois:['Bois','#d9b98c'],noir:['Noir','#20242c'],transparent:['Transparent','transparent']};
function uvLogo(){const s=state.uvSupport,bg=supports[s][1],white=state.uvWhite;const blend=white?'normal':'multiply';const checker=s==='transparent'?`<defs><pattern id="chk" width="24" height="24" patternUnits="userSpaceOnUse"><rect width="24" height="24" fill="#c9ccd4"/><rect width="12" height="12" fill="#eef0f4"/><rect x="12" y="12" width="12" height="12" fill="#eef0f4"/></pattern></defs><rect x="70" y="40" width="460" height="260" rx="14" fill="url(#chk)"/><rect x="70" y="40" width="460" height="260" rx="14" fill="#ffffff" opacity=".12" stroke="#9aa1ad" stroke-width="2"/>`:`<rect x="70" y="40" width="460" height="260" rx="14" fill="${bg}" stroke="#9aa1ad" stroke-width="2"/>`;const op=s==='transparent'&&!white?.55:1;return `<svg viewBox="0 0 600 340" role="img" aria-label="Logo imprimé sur un support ${supports[s][0].toLowerCase()}, ${white?'avec':'sans'} couche de blanc."><rect width="600" height="340" fill="#f4f3f8"/>${checker}${white?`<g fill="#fff"><circle cx="230" cy="170" r="70"/><rect x="320" y="110" width="150" height="120" rx="12"/></g>`:''}<g style="mix-blend-mode:${blend}" opacity="${op}"><circle cx="230" cy="170" r="70" fill="${flash}"/><circle cx="230" cy="170" r="38" fill="#f2c230"/><rect x="320" y="110" width="150" height="120" rx="12" fill="${fuchsia}"/></g></svg>`;}
function pixelSVG(){const hi=state.uvHiRes;if(hi)return `<svg viewBox="0 0 600 340" role="img" aria-label="Image en bonne résolution : un cercle aux bords nets."><rect width="600" height="340" fill="#f4f3f8"/><circle cx="300" cy="170" r="120" fill="${mauve}"/><circle cx="300" cy="170" r="60" fill="${flash}"/></svg>`;let px='';const n=12,size=240/n;for(let y=0;y<n;y++)for(let x=0;x<n;x++){const cx=(x+.5)*size-120,cy=(y+.5)*size-120,d=Math.hypot(cx,cy);if(d<120)px+=`<rect x="${180+x*size}" y="${50+y*size}" width="${size+.5}" height="${size+.5}" fill="${d<60?flash:mauve}"/>`;}return `<svg viewBox="0 0 600 340" role="img" aria-label="Image en basse résolution agrandie : le cercle apparaît en gros carrés, en escalier."><rect width="600" height="340" fill="#f4f3f8"/>${px}</svg>`;}
function uvStepHTML(i){if(i===0)return `<div class="layer-demo">${pixelSVG()}</div><div class="p2-layer-btns" role="group" aria-label="Résolution de l’image"><button class="pill" data-hires="1" aria-pressed="${state.uvHiRes}">Assez de pixels</button><button class="pill" data-hires="0" aria-pressed="${!state.uvHiRes}">Petite image agrandie</button></div>`;if(i===1)return `<div class="layer-demo"><svg viewBox="0 0 600 340" role="img" aria-label="Vue de côté : la tête d’impression UV passe quelques millimètres au-dessus d’un carreau posé à plat ; une lampe UV suit la tête."><rect width="600" height="340" fill="#f4f3f8"/><rect x="200" y="70" width="140" height="80" rx="8" fill="${ink}"/><rect x="345" y="110" width="50" height="40" rx="6" fill="#4a4f8f"/><path d="M370 150l-20 70M370 150l20 70" stroke="#8d7cf0" stroke-width="2" opacity=".7"/><g fill="${flash}"><circle cx="235" cy="175" r="4"/><circle cx="260" cy="190" r="4"/><circle cx="285" cy="178" r="4"/><circle cx="310" cy="195" r="4"/></g><rect x="120" y="220" width="360" height="26" fill="#fff" stroke="#9aa1ad" stroke-width="2"/><path d="M90 246h420" stroke="#6b7280" stroke-width="6"/><text x="120" y="282" font-family="Poppins,Arial,sans-serif" font-size="16" fill="${ink}">Carreau posé à plat · tête à quelques millimètres</text><text x="400" y="104" font-family="Poppins,Arial,sans-serif" font-size="15" fill="${ink}">lampe UV</text></svg></div>`;if(i===2)return `<div class="layer-demo" id="uv-drawing">${uvLogo()}</div><div class="p2-layer-btns" role="group" aria-label="Support">${Object.entries(supports).map(([k,[n]])=>`<button class="pill" data-support="${k}" aria-pressed="${state.uvSupport===k}">${n}</button>`).join('')}</div><label class="check p2-white"><input type="checkbox" id="uv-white" ${state.uvWhite?'checked':''}><span>Ajouter une couche de blanc sous la couleur</span></label><p class="small" role="status">${uvFeedback()}</p>`;return `<div class="layer-demo"><svg viewBox="0 0 600 340" role="img" aria-label="Couches empilées vues de côté : support, blanc, couleur, vernis. Chaque couche est durcie par la lumière UV."><rect width="600" height="340" fill="#f4f3f8"/><rect x="120" y="250" width="360" height="40" fill="#20242c"/><rect x="120" y="232" width="360" height="18" fill="#fff" stroke="#c9ccd4"/><rect x="120" y="214" width="360" height="18" fill="${fuchsia}"/><rect x="200" y="196" width="200" height="18" fill="#e7ecf5" stroke="#c9ccd4"/><g font-family="Poppins,Arial,sans-serif" font-size="15" fill="${ink}"><text x="490" y="276">support</text><text x="490" y="246">blanc</text><text x="490" y="228">couleur</text><text x="410" y="210">vernis</text></g><path d="M300 40v120" stroke="#8d7cf0" stroke-width="3" stroke-dasharray="6 6"/><text x="312" y="70" font-family="Poppins,Arial,sans-serif" font-size="15" fill="${ink}">lumière UV : l’encre durcit</text></svg></div>`;}
function uvFeedback(){const s=state.uvSupport,w=state.uvWhite;if(s==='blanc')return w?'Sur du blanc, la couche de blanc change peu : elle consomme de l’encre et du temps.':'Sur un support blanc, les couleurs ressortent déjà bien.';if(s==='bois')return w?'Le blanc rend les couleurs plus vives et fidèles sur le bois.':'Sur le bois, les couleurs se mélangent à la teinte du support : c’est parfois l’effet recherché.';if(s==='noir')return w?'Avec le blanc dessous, les couleurs redeviennent visibles et lumineuses.':'Sans blanc, la couleur disparaît presque sur le noir.';return w?'Le blanc rend l’image opaque : elle se voit de loin.':'Sans blanc, l’image reste transparente, comme un vitrail.';}
function screen4(){const i=state.uvStep,s=uvSteps[i];return `${kicker(4)}<div class="section-head"><h2>Une image.<br><span class="orange">Posée sur l’objet.</span></h2><p class="lede">Du visuel à l’impression,<br>quatre étapes à comprendre.</p></div>${stepsTabs(uvSteps,'uvStep','ustep')}<div class="split process-layout"><div>${uvStepHTML(i)}</div><div class="process-copy"><span class="number">ÉTAPE 0${i+1}</span><h3>${s[0]}</h3><p class="lede">${s[1]}</p><p class="notice">${s[2]}</p><div class="challenge"><span class="symbol" aria-hidden="true">?</span><p>${s[3]}</p></div>${i===3?`<button class="text-link" data-source="roland">Repères sur l’impression UV ↗</button>`:''}</div></div>`;}

// ——— Matériaux ———
const V={ok:['Oui','ok'],att:['Avec précaution','att'],no:['Non','no'],ban:['Interdit','ban']};
const materialsP2={
 bois:{name:'Contreplaqué & MDF',cut:'ok',eng:'ok',uv:'ok',note:'Le grand classique de l’atelier. Le MDF produit beaucoup de fumée : l’aspiration est indispensable. L’épaisseur qu’on peut couper dépend de la machine.'},
 acry:{name:'Acrylique (PMMA)',cut:'ok',eng:'ok',uv:'ok',note:'Bords de coupe nets et brillants. Gravé, il devient blanc dépoli. En UV, vérifie l’accroche selon la référence.'},
 carton:{name:'Carton & papier',cut:'ok',eng:'ok',uv:'ok',note:'Se découpe très vite, mais s’enflamme facilement : surveillance renforcée.'},
 cuir:{name:'Cuir naturel',cut:'ok',eng:'ok',uv:'att',note:'Odeur forte à la découpe. Attention : le similicuir contient souvent du PVC — interdit au laser.'},
 verre:{name:'Verre',cut:'no',eng:'ok',uv:'att',note:'Le laser ne le coupe pas mais peut le dépolir en surface. En UV, une préparation est souvent nécessaire pour que l’encre accroche.'},
 metal:{name:'Métal',cut:'no',eng:'att',uv:'att',note:'Un laser d’atelier classique (CO₂) ne coupe pas le métal. Le marquage demande un produit ou un laser spécifique. En UV, préparation de surface nécessaire.'},
 ceram:{name:'Céramique & carrelage',cut:'no',eng:'att',uv:'ok',note:'Support idéal pour l’UV, à condition de suivre la procédure de préparation et de finition de l’atelier.'},
 pvc:{name:'PVC, vinyle, similicuir',cut:'ban',eng:'ban',uv:'ok',note:'Interdit au laser : en chauffant, il dégage du chlore, toxique pour toi et corrosif pour la machine. En revanche, l’UV imprime très bien sur beaucoup de vinyles.'}
};
function verdict(k){const [l,c]=V[k];return `<span class="p2-verdict ${c}">${l}</span>`;}
function screen5(){const m=materialsP2[state.material];return `${kicker(5)}<div class="section-head"><h2>Tout ne passe pas<br><span class="orange">dans la machine.</span></h2><p class="lede">Choisis une matière.<br>Couper, graver, imprimer : devine d’abord.</p></div><div class="p2-materials" role="group" aria-label="Matières">${Object.entries(materialsP2).map(([k,x])=>`<button class="p2-mat${k==='pvc'?' danger':''}" data-mat="${k}" aria-pressed="${state.material===k}">${x.name}</button>`).join('')}</div><div class="p2-mat-card" role="status"><h3>${m.name}</h3><div class="p2-verdicts"><div><span class="micro muted">DÉCOUPE LASER</span>${verdict(m.cut)}</div><div><span class="micro muted">GRAVURE LASER</span>${verdict(m.eng)}</div><div><span class="micro muted">IMPRESSION UV</span>${verdict(m.uv)}</div></div><p class="body">${m.note}</p></div><p class="small muted" style="margin-top:14px">Repères généraux pour un laser CO₂ et une imprimante UV d’atelier. La liste des matières autorisées de ta machine fait toujours foi. Une matière inconnue ne passe pas au laser.</p><button class="text-link" data-source="trotecMat">Matières non adaptées au laser ↗</button>`;}

// ——— Vrai ou faux ———
const truths=[
 ['Je peux découper une vieille carte en plastique.','Faux','Beaucoup de cartes sont en PVC, interdit au laser. Une matière dont on ne connaît pas la composition ne passe jamais au laser.'],
 ['Pendant la découpe, je peux aller chercher un café.','Faux','Une flamme peut apparaître à tout moment. Quelqu’un reste près du laser pendant toute la découpe.'],
 ['Le laser coupe n’importe quelle épaisseur.','Faux','Au-delà d’une certaine épaisseur, il ne traverse plus ou brûle les bords. La limite dépend de la machine et de la matière.'],
 ['Une impression UV sort sèche de la machine.','Vrai','La lampe UV durcit l’encre juste après son dépôt. On peut manipuler l’objet tout de suite.'],
 ['On peut imprimer en UV sur une balle de tennis.','Faux','La tête passe à plat, à quelques millimètres. Les formes rondes ou très bombées demandent un accessoire spécial, ou ne conviennent pas.'],
 ['Le laser peut graver une photo.','Vrai','Il traduit les nuances de gris en points plus ou moins denses. Le rendu reste d’une seule teinte, celle de la matière brûlée.']
];
function screen6(){return `${kicker(6)}<div class="section-head"><h2>Vrai ou faux ?<br><span class="orange">Vote, puis retourne.</span></h2><p class="lede">Six affirmations.<br>Lève la main avant de toucher la carte.</p></div><div class="limits p2-truths">${truths.map(([q,a,why],i)=>{const open=state.truths.includes(i);return `<button class="limit-card" data-truth="${i}" aria-pressed="${open}" aria-expanded="${open}"><span class="limit-no">0${i+1}</span><strong>${q}</strong>${open?`<p><span class="p2-tf ${a==='Vrai'?'ok':'no'}">${a}</span> ${why}</p>`:`<p class="muted">Touche pour retourner.</p>`}</button>`;}).join('')}</div><p class="notice" style="margin-top:20px">Avant chaque lancement, le formateur valide la matière, le fichier et les réglages. C’est la règle de l’atelier.</p>`;}

// ——— À toi de créer ———
function screen7(){const link=APP_URL?`<a class="primary" href="${escape(APP_URL)}" target="_blank" rel="noopener">Ouvrir l’appli de création <span aria-hidden="true">↗</span></a>`:`<p class="p2-app-pending"><strong>Lien de l’appli à venir.</strong> Le formateur te le donnera au moment de l’exercice.</p>`;return `${kicker(7)}<div class="section-head"><h2>Ton idée.<br><span class="orange">Ta réalisation.</span></h2><p class="lede">Passe de l’écran à la matière<br>avec l’appli de création.</p></div><div class="split"><div class="workshop-note"><span class="micro">EXERCICE FINAL · 30 MINUTES</span><h2>Crée.<br>Vérifie.<br>Fabrique.</h2><div>${link}</div></div><ol class="brief-rules p2-create"><li><span>1</span><div><strong>Ouvre l’appli</strong><p>Sur ta tablette, avec le lien donné par le formateur.</p></div></li><li><span>2</span><div><strong>Crée ton visuel</strong><p>Pense à la machine : découpe, gravure ou impression couleur ?</p></div></li><li><span>3</span><div><strong>Montre ton fichier</strong><p>Le formateur vérifie la matière, la taille et la durée avant de lancer.</p></div></li><li><span>4</span><div><strong>Observe la fabrication</strong><p>À distance, capot fermé. Récupère ton objet quand le formateur te le dit.</p></div></li></ol></div>`;}

// ——— Bilan ———
function screen8(){return `${kicker(8)}<div class="finish closing"><div><span class="finish-tag">L’OBJET EN MAIN · DERNIER TOUR DE PAROLE</span><h1>De la lumière<br>à ta main.<br><span class="orange">Qu’as-tu découvert ?</span></h1><p class="lede">Regarde ton objet. Repense à sa fabrication. Raconte ce que la machine t’a appris.</p><div class="finish-actions"><button class="text-link" data-source="all">Sources et repères ↗</button><a class="text-link" href="index.html#intro">Revoir la partie 1 · Impression 3D</a></div></div><div class="closing-card"><span class="eyebrow">30 SECONDES POUR PARTAGER</span><ol><li><span>01</span><strong>Montre un détail</strong><p>Un bord coupé, une gravure, une couleur, une couche de blanc.</p></li><li><span>02</span><strong>Choisis ta machine</strong><p>Pour ton prochain objet : laser, UV, ou les deux ?</p></li><li><span>03</span><strong>Dis ce que tu vérifierais</strong><p>Avant de lancer une vraie fabrication.</p></li></ol></div></div>`;}

const screens=[screen0,screen1,screen2,screen3,screen4,screen5,screen6,screen7,screen8];
const LAST=screens.length-1;
function kicker(i){return `<div class="kicker-line"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${plan[i][0]} <span class="time">${plan[i][1]} MIN</span></div><span class="label">Partie 2 · Laser &amp; UV</span></div>`;}
function toggle(arr,n){return arr.includes(n)?arr.filter(x=>x!==n):[...arr,n];}
function refocus(sel){return ()=>$(sel)?.focus({preventScroll:true});}

function render(focus=false){state.page=Math.max(0,Math.min(LAST,Number(state.page)||0));const p=state.page;$('#stage').innerHTML=screens[p]();$('#stage').classList.remove('fade-in');void $('#stage').offsetWidth;$('#stage').classList.add('fade-in');$('#page-number').textContent=`${String(p+1).padStart(2,'0')} / ${String(screens.length).padStart(2,'0')}`;$('#chapter-name').textContent=plan[p][0];$('#progress').style.width=`${(p+1)/screens.length*100}%`;$('#prev').disabled=p===0;$('#next').disabled=p===LAST;$('#next').innerHTML=p===LAST?'Atelier terminé ✓':`${plan[p+1][0]} <span aria-hidden="true">→</span>`;$('#dots').innerHTML=plan.map((s,i)=>`<button class="dot" data-go="${i}" aria-label="Étape ${i+1} : ${s[0]}" ${i===p?'aria-current="step"':''}></button>`).join('');$('#announcement').textContent=`Étape ${p+1} sur ${screens.length} : ${plan[p][0]}`;bind();save();if(focus){$('#stage').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function rerender(sel){render();if(sel)refocus(sel)();}
function go(n){if(!Number.isInteger(n)||n<0||n>LAST)return;document.body.classList.remove('intro-active');state.page=n;history.replaceState(null,'',`#etape-${n+1}`);render(true);}
function updateCut(){const d=$('#cut-drawing');if(!d)return;d.innerHTML=cutSVG();const [l,t]=laserResult();$('#cut-status').innerHTML=`<strong>${l}.</strong> ${t}`;$('#power-out').textContent=`${state.power} %`;$('#speed-out').textContent=`${state.speed} %`;}
function bind(){
 $$('[data-scenario]').forEach(b=>b.onclick=()=>{state.scenario=+b.dataset.scenario;rerender(`[data-scenario="${state.scenario}"]`);});
 $$('[data-sector]').forEach(b=>b.onclick=()=>{state.sector=+b.dataset.sector;rerender(`[data-sector="${state.sector}"]`);});
 $$('.p2-case-photo img').forEach(img=>img.addEventListener('error',()=>{const f=img.closest('figure');if(f)f.classList.add('p2-photo-missing');img.remove();},{once:true}));
 $$('[data-case]').forEach(b=>b.onclick=()=>{const i=+b.dataset.case,key=`c-${state.sector}-${i}`;state.reveal={...state.reveal,[key]:state.reveal?.[key]?0:1};rerender(`[data-case="${i}"]`);});
 $$('[data-reveal]').forEach(b=>b.onclick=()=>{state.reveal={...state.reveal,[b.dataset.reveal]:1};rerender('.p2-answer p');});
 $$('[data-quiz]').forEach(b=>b.onclick=()=>{const i=b.dataset.quiz;state.quiz={...state.quiz,[i]:b.dataset.answer};rerender(`[data-quiz="${i}"][data-answer="${b.dataset.answer}"]`);});
 $$('[data-lstep]').forEach(b=>b.onclick=()=>{state.laserStep=+b.dataset.lstep;rerender(`[data-lstep="${state.laserStep}"]`);});
 $$('[data-ustep]').forEach(b=>b.onclick=()=>{state.uvStep=+b.dataset.ustep;rerender(`[data-ustep="${state.uvStep}"]`);});
 $$('[data-layer]').forEach(b=>b.onclick=()=>{state.laserLayer=b.dataset.layer;rerender(`[data-layer="${state.laserLayer}"]`);});
 $$('[data-support]').forEach(b=>b.onclick=()=>{state.uvSupport=b.dataset.support;rerender(`[data-support="${state.uvSupport}"]`);});
 $$('[data-hires]').forEach(b=>b.onclick=()=>{state.uvHiRes=b.dataset.hires==='1';rerender(`[data-hires="${b.dataset.hires}"]`);});
 $('#uv-white')?.addEventListener('change',e=>{state.uvWhite=e.target.checked;rerender('#uv-white');});
 ['power','speed'].forEach(id=>$('#'+id)?.addEventListener('input',e=>{state[id]=+e.target.value;updateCut();save();}));
 $$('[data-mat]').forEach(b=>b.onclick=()=>{state.material=b.dataset.mat;rerender(`[data-mat="${state.material}"]`);});
 $$('[data-truth]').forEach(b=>b.onclick=()=>{const i=+b.dataset.truth;state.truths=toggle(state.truths,i);rerender(`[data-truth="${i}"]`);});
 $$('[data-go]').forEach(b=>b.onclick=()=>go(+b.dataset.go));$$('[data-source]').forEach(b=>b.onclick=()=>showSources(b.dataset.source));
}
let modalOpener=null;
function openModal(k,html){modalOpener=document.activeElement;$('#modal-kicker').textContent=k;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;$('#close-modal').focus();}
function closeModal(){$('#modal').close();modalOpener?.focus?.();}
function showSources(which){const keys=which==='all'?Object.keys(sources):[which];openModal('SOURCES & REPÈRES',`<h2 class="modal-title">Pour aller vérifier.</h2><p class="small">Repères généraux. La documentation et la procédure de chaque machine de l’atelier font foi.</p><div class="sources">${keys.map(k=>{const s=sources[k];return `<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><p class="small muted">${s.author}<br>${s.note}</p>`;}).join('')}</div><div class="guide-block" style="margin-top:24px"><h3>À propos des images</h3><p>Les schémas de cette partie sont des illustrations de principe. La photo de l’imprimante UV sur carreaux est un visuel d’illustration fourni pour l’atelier. Les photos des usages métiers sont affichées depuis les témoignages clients de Trotec Laser, avec leur crédit ; les cas et les chiffres proviennent de ces pages, consultées le 3 novembre 2026.</p></div>`);}
function showGuide(){const p=plan[state.page];openModal('GUIDE ANIMATEUR · PARTIE 2',`<h2 class="modal-title">${p[0]} <span class="orange">${p[1]} min</span></h2><p class="guide-quote">« ${p[3]} »</p><div class="guide-block"><h3>À faire maintenant</h3><p>${p[4]}</p></div><div class="guide-block"><h3>À faire comprendre</h3><p>${p[5]}</p></div><div class="guide-block"><h3>Avant l’arrivée du groupe</h3><ul><li>Vérifie l’aspiration du laser, le filtre et l’extincteur adapté à portée de main. Garde une chute de chaque matière pour les tests.</li><li>Prépare une plaque de test avec plusieurs réglages de puissance et de vitesse, et un échantillon UV imprimé avec et sans blanc.</li><li>Rassemble des échantillons de matières : bois, acrylique, carton, cuir, verre, céramique — et un morceau de PVC étiqueté « interdit au laser ».</li><li>Vérifie la procédure de préparation des supports UV (nettoyage, primaire, vernis) et le niveau des encres, dont le blanc.</li><li>Prépare le lien de l’appli de création et teste un export complet jusqu’à la machine.</li></ul></div><div class="guide-block"><h3>Piloter l’atelier</h3><p>Les flèches et les repères en bas de page donnent accès à chaque écran. Les flèches du clavier fonctionnent aussi. Aucune étape n’avance toute seule. Le chrono mesure l’atelier ; il ne lit pas l’état des machines.</p><p class="small muted" style="margin-top:10px">Les photos des cas métiers se chargent depuis Internet : vérifie la connexion des tablettes. Les réponses et le chrono restent dans cet onglet pendant la session.</p><button class="text-link" id="open-sources">Voir toutes les sources ↗</button><br><button class="text-link" id="reset-session">Préparer une nouvelle séance</button></div>`);$('#open-sources').onclick=()=>showSources('all');$('#reset-session').onclick=()=>{openModal('NOUVELLE SÉANCE',`<h2 class="modal-title">Remettre la partie 2 à zéro ?</h2><p class="body">Le chrono et les réponses de cet onglet seront effacés.</p><div class="finish-actions"><button class="primary" id="reset-confirm">Réinitialiser la séance</button><button class="pill" id="reset-cancel">Garder cette séance</button></div>`);$('#reset-cancel').onclick=showGuide;$('#reset-confirm').onclick=()=>{state=JSON.parse(JSON.stringify(initial));save();closeModal();showIntro();tick();};};}
function tick(){const total=Math.floor(elapsed()/1000);$('#clock-text').textContent=total||state.runningSince?`${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`:'Démarrer';$('#clock').setAttribute('aria-label',state.runningSince?'Mettre en pause le chrono de l’atelier':'Démarrer ou reprendre le chrono de l’atelier');$('#clock').firstChild.textContent=state.runningSince?'Ⅱ ':'▷ ';}
function showIntro(focus=true){document.body.classList.add('intro-active');history.replaceState(null,'','#intro');window.scrollTo({top:0,behavior:'instant'});if(focus)$('#intro-title').focus({preventScroll:true});}

$('#prev').onclick=()=>go(state.page-1);$('#next').onclick=()=>go(state.page+1);$('#home').onclick=()=>showIntro();$('#guide').onclick=showGuide;$('#close-modal').onclick=closeModal;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#clock').onclick=()=>{if(state.runningSince){state.elapsed=elapsed();state.runningSince=null;}else{state.runningSince=Date.now();}save();tick();};
document.addEventListener('keydown',e=>{if(document.body.classList.contains('intro-active'))return;if($('#modal').open||e.altKey||e.ctrlKey||e.metaKey||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowRight'){e.preventDefault();go(state.page+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.page-1);}});
const pageFromHash=()=>Number(location.hash.match(/^#etape-(\d+)$/)?.[1]);
window.addEventListener('hashchange',()=>{if(!location.hash||location.hash==='#intro'){showIntro(false);return;}const n=pageFromHash();if(n>=1&&n<=screens.length){document.body.classList.remove('intro-active');state.page=n-1;render(true);}});
const hashPage=pageFromHash();if(hashPage>=1&&hashPage<=screens.length)state.page=hashPage-1;
$('#enter-workshop').onclick=()=>{state.scenario=0;go(0);};
render();if(hashPage>=1&&hashPage<=screens.length)document.body.classList.remove('intro-active');else showIntro(false);
tick();setInterval(tick,1000);
